// Classify the event and work out everything the Supabase calls need, so the
// branches below stay dumb.
const ev = $input.first().json;
const type = ev.type;
const obj = (ev.data && ev.data.object) || {};

// PAYGO is exactly 85c per render credit.
//
// The old workflow used amount_total, which includes automatic tax: a single
// credit arrives as 90c and 90/85 = 1.0588, which floored to 1 only by luck and
// broke outright at higher quantities (10 credits = 900c total, 900/85 = 10.58).
// amount_subtotal is pre-tax, so it stays an exact multiple of 85 at any
// quantity the payment link allows, and survives any future tax-rate change.
function creditsFrom(session){
  const sub = Number(session.amount_subtotal);
  if (!Number.isFinite(sub) || sub <= 0) return 0;
  return Math.floor(sub / 85);
}

// Matched on the pre-tax amount for the same reason.
const PLANS = [
  { cents: 500,  name: 'Starter' },
  { cents: 1000, name: 'Crew' },
  { cents: 2000, name: 'Pro' },
  { cents: 4000, name: 'Studio' }
];
function planFrom(cents){
  const hit = PLANS.find(p => p.cents === Number(cents));
  return hit ? hit.name : null;
}

let out = { action: 'ignore', type: type };

if (type === 'checkout.session.completed'){
  const uid = obj.client_reference_id || null;
  const customer = obj.customer || null;
  if (obj.mode === 'payment'){
    out = { action: 'credits', type, uid, customer, credits: creditsFrom(obj) };
  } else if (obj.mode === 'subscription'){
    const cents = obj.amount_subtotal != null ? obj.amount_subtotal : obj.amount_total;
    out = { action: 'subscribe', type, uid, customer, plan: planFrom(cents) };
  }
} else if (type === 'customer.subscription.deleted'){
  // Matched on stripe_customer_id, because a cancellation payload carries no
  // client_reference_id the way a checkout session does.
  out = { action: 'cancel', type, customer: obj.customer || null };
} else if (type === 'invoice.paid'){
  // Only real renewals. The first invoice of a subscription arrives as
  // 'subscription_create' and is already handled by the checkout branch.
  if (obj.billing_reason === 'subscription_cycle'){
    out = { action: 'renew', type, customer: obj.customer || null };
  }
}

return [{ json: out }];
